import sys, json, random, itertools, subprocess; sys.path.insert(0,'/workspace/tmp_tests')
import ref
from harness import ok

def gen(rng):
    # random zone tree
    origins = rng.sample(['test.','sub.test.','a.sub.test.','.','deep.x.test.','other.'], rng.randint(1,4))
    origins = list(dict.fromkeys(origins))
    names_pool = ['test.','sub.test.','a.sub.test.','b.a.sub.test.','deep.x.test.','x.test.','y.x.test.',
                  '*.test.','*.sub.test.','*.x.test.','leaf.test.','other.','out.example.','*.',
                  'deep.x.test.','*.deep.x.test.','c1.test.','c2.test.','c3.test.']
    zones=[]
    for org in origins:
        recs=[]
        for _ in range(rng.randint(0,7)):
            cand=[n for n in names_pool if ref.below(ref.canon_name(n), ref.canon_name(org))]
            if not cand: continue
            owner=rng.choice(cand)
            t=rng.choice(['A','AAAA','TXT','CNAME'])
            if t=='A': data='192.0.%d.%d'%(rng.randrange(256),rng.randrange(1,255))
            elif t=='AAAA': data=rng.choice(['2001:db8::1','::1','FE80::%x'%rng.randrange(1,255),'2001:DB8:0:0:0:0:2:1'])
            elif t=='TXT': data=rng.choice(['','hello','x'*256,'a b c!','~!@#'])
            else: data=rng.choice(names_pool)
            recs.append({'owner':owner,'type':t,'data':data})
        # enforce CNAME exclusivity
        byowner={}
        for r in recs:
            byowner.setdefault(ref.canon_name(r['owner']).lower(),[]).append(r)
        final=[]
        for owner, rs in byowner.items():
            if any(r['type']=='CNAME' for r in rs):
                cn=[r for r in rs if r['type']=='CNAME']
                tgt=cn[0]['data']
                if owner == ref.canon_name(org):
                    continue
                final.append({'owner':rs[0]['owner'],'type':'CNAME','data':tgt})
            else:
                seen=set()
                for r in rs:
                    k=(r['owner'].lower(),r['type'],r['data'])
                    if k in seen: continue
                    seen.add(k); final.append(r)
        zones.append({'origin':org,'records':final})
    profiles=[]
    for i in range(rng.randint(1,5)):
        profiles.append({'id':rng.choice(['p','q','r','s','t','u','A','B','z%d'%i]),
                         'max_aliases':rng.choice([0,1,2,3,64]),
                         'cname':rng.choice(['follow','stop']),
                         'wildcard':rng.choice(['rfc','off','one-label'])})
    seen=set(); profiles=[p for p in profiles if not (p['id'] in seen or seen.add(p['id']))]
    if not profiles: profiles=[{'id':'p','max_aliases':1,'cname':'follow','wildcard':'rfc'}]
    queries=[]
    qseen=set()
    for i in range(rng.randint(0,8)):
        qid='q%d'%i
        queries.append({'id':qid,'name':rng.choice(names_pool+['UPPER.Test.','*.X.TEST.']),
                        'type':rng.choice(['A','AAAA','TXT','CNAME']),'cost':rng.randint(1,12)})
    obs=[]
    for i in range(rng.randint(0,6)):
        if not queries: break
        oid='o%d'%i
        if rng.random()<0.3:
            res={'status':'timeout'}
        else:
            n=rng.randint(0,3)
            ans=[{'owner':rng.choice(names_pool),'type':rng.choice(['A','TXT']),'data':rng.choice(['192.0.2.1','198.51.100.7','hi'])} for _ in range(n)]
            res={'status':'response','rcode':rng.choice(['NOERROR','NXDOMAIN','SERVFAIL','REFUSED']),'answer':ans}
        obs.append({'id':oid,'query':rng.choice(queries)['id'],'profile':rng.choice(profiles)['id'],'result':res})
    return {'zones':zones,'profiles':profiles,'queries':queries,'observations':obs}

rng = random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 42)
bad_count=0
for trial in range(600):
    doc = gen(rng)
    try:
        actual = ok(doc)
    except AssertionError as e:
        print('trial',trial,'REJECTED by submission:', str(e)[:300])
        print(json.dumps(doc)[:1200])
        bad_count+=1
        continue
    try:
        expected = ref.analyze(doc)
    except RecursionError:
        continue
    if actual['runs'] != expected['runs']:
        print('RUNS MISMATCH trial', trial)
        for a,b in zip(actual['runs'], expected['runs']):
            if a!=b: print(' A:',json.dumps(a)); print(' B:',json.dumps(b))
        print(json.dumps(doc)[:2000]); bad_count+=1; break
    if actual['audits'] != expected['audits']:
        print('AUDIT MISMATCH trial', trial); print(json.dumps(actual['audits'])); print(json.dumps(expected['audits']))
        print(json.dumps(doc)[:2000]); bad_count+=1; break
    da, de = actual['diagnostic'], expected['diagnostic']
    if da['equivalence'] != de['equivalence']:
        print('EQUIV MISMATCH', trial, da['equivalence'], de['equivalence']); bad_count+=1; break
    if (da['cost'],da['count']) != (de['cost'],de['count']):
        print('BASIS COST MISMATCH', trial, da, de); print(json.dumps(doc)[:2000]); bad_count+=1; break
    # basis validity
    pids=sorted(p['id'] for p in doc['profiles']); qids=sorted(q['id'] for q in doc['queries'])
    m={(r['query'],r['profile']):(r['rcode'],frozenset((x['owner'],x['type'],x['data']) for x in r['answer'])) for r in expected['runs']}
    for a,b in itertools.combinations(pids,2):
        if any(m[(q,a)]!=m[(q,b)] for q in qids):
            assert any(m[(q,a)]!=m[(q,b)] for q in da['basis']), (trial,a,b)
    if bad_count: break
print('FUZZ done, failures:', bad_count)
